pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address actor;
    uint256 amount1;
    uint256 amount2;

    function testFuzz_property(uint256 a1, uint256 a2, address a) public {
        actor = a == address(0) ? address(0xBEEF) : a;
        amount1 = bound(a1, 1, 10 ether);
        amount2 = bound(a2, 1, 10 ether);

        Accepter target = new Accepter();

        // owner deposits amount1 into c via receive
        vm.deal(address(this), amount1);
        (bool s1,) = address(c).call{value: amount1}("");
        assertTrue(s1);
        assertTrue(address(c).balance == amount1);

        // owner calls Command with a fresh msg.value = amount2
        vm.deal(actor, amount2);
        vm.prank(actor);
        c.Command(address(target), "");

        // Rule: c forwards exactly msg.value, so the prior deposit amount1 stays in c
        assertTrue(address(c).balance == amount1);
    }

    receive() external payable {}
}

contract Accepter {
    receive() external payable {}
}

