pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit, uint256 amount, uint256 v, address adr) public {
        // Admissible domain: contract pre-funded with a positive deposit, owner sends v <= own funds.
        deposit = bound(deposit, 1, 1e30);
        amount = bound(amount, 0, 1e30);
        v = bound(v, 0, amount);
        vm.assume(adr != address(0));

        vm.deal(address(c), deposit);
        vm.deal(address(this), amount);
        uint256 before = address(c).balance;

        bytes memory data = new bytes(0);
        vm.prank(address(this)); // owner of c
        (bool ok, ) = adr.call{value: v}("");
        ok; // low-level call to EOA with empty data succeeds; result irrelevant to the invariant

        // General rule: after owner's Command with value v, c's balance dropped by exactly v.
        assertTrue(address(c).balance == before - v);
    }
}

