pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit, uint256 amount, address adr) public {
        // Admissible domain: a positive pre-existing deposit in c, a positive
        // forwarded amount not exceeding c's balance, and a codeless receiver
        // (plain EOA, whose low-level call always succeeds) distinct from c.
        deposit = bound(deposit, 1, type(uint128).max);
        vm.assume(adr != address(c) && adr != address(this) && adr.code.length == 0);

        // Fund the test contract (the owner, since it deployed c) and build a
        // pre-existing deposit inside c via its receive() payable fallback.
        vm.deal(address(this), deposit);
        (bool dep, ) = address(c).call{value: deposit}("");
        require(dep, "deposit failed");

        // Bound the value sent through Command to what c can actually forward.
        amount = bound(amount, 1, address(c).balance);

        // Drive c through Command as the Owner (empty calldata to the EOA).
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Command.selector, adr, "")
        );
        require(ok, "Command failed");

        // General rule: an owner-issued Command{value: amount} deducts exactly
        // `amount` from c's balance; the pre-existing deposit stays in c.
        // The mutant forwards address(this).balance instead, leaving c at 0.
        assertTrue(address(c).balance == deposit - amount);
    }
}

