import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 deposit) public {
        amount = bound(amount, 1, 1e30);
        deposit = bound(deposit, 1, 1e30);

        Receiver r = new Receiver();
        vm.deal(address(this), amount);
        vm.deal(address(c), deposit);

        uint256 before = address(c).balance;

        // test contract is the Owner (deployer), so it may call Command
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Command.selector, address(r), "")
        );
        assertTrue(ok);

        // Reference: only msg.value is forwarded, so c's balance is unchanged.
        // Mutant: the whole balance is forwarded, draining c to 0.
        assertTrue(address(c).balance == before);
    }
}

