pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor, address adr) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(c) && adr != address(c));
        amount = bound(amount, 1, 1e30);

        // fund c so its balance equals amount
        vm.deal(actor, amount);
        vm.prank(actor);
        payable(address(c)).transfer(amount);
        require(address(c).balance == amount, "setup failed");

        // call multiplicate with msg.value == address(c).balance
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.multiplicate.selector, adr)
        );
        assertTrue(ok);

        // Reference: transfer sends balance + msg.value, so c is emptied.
        // Mutant: strict '>' skips the transfer, so c keeps its balance.
        assertTrue(address(c).balance == 0, "entire balance must be transferred out");
    }
}

