import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seedBalance, uint256 amount, address adr) public {
        vm.assume(adr != address(0));
        vm.assume(adr != address(c));
        seedBalance = bound(seedBalance, 0, 1e30);
        amount = bound(amount, 0, 1e30);
        vm.assume(seedBalance + amount <= type(uint256).max);

        // seed the contract's balance
        vm.deal(address(c), seedBalance);

        // caller must be able to pay `amount`
        address caller = address(0xBEEF);
        vm.deal(caller, amount);

        vm.prank(caller);
        c.multiplicate{value: amount}(adr);

        // GENERAL RULE: after a multiplicate call with msg.value >= balance,
        // the contract sends its entire balance + msg.value away -> empty contract.
        assertTrue(address(c).balance == 0, "multiplicate must drain the full balance plus msg.value");
    }
}

